import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"中孚","description":"周易正義 - 中孚","frontmatter":{"title":"中孚","description":"周易正義 - 中孚"},"headers":[],"relativePath":"classics/zhengyi/061.md","filePath":"classics/zhengyi/061.md"}'),l={name:"classics/zhengyi/061.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<blockquote><p>風澤中孚</p></blockquote><blockquote><p>卦辭：豚魚吉，利涉大川，利貞。</p></blockquote><blockquote><p>彖曰：中孚，柔在內而剛得中，說而巽，孚乃化邦也。豚魚吉，信及豚魚也。利涉大川，乘木舟虛也。中孚以利貞，乃應乎天也。</p></blockquote><h1 id="中孚" tabindex="-1">中孚 <a class="header-anchor" href="#中孚" aria-label="Permalink to “中孚”">​</a></h1><h3 id="疏" tabindex="-1">疏 <a class="header-anchor" href="#疏" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“中孚，豚魚吉”者，“中孚”，卦名也。信發於中，謂之中孚。魚者，蟲之幽隱。豚者，獸之微賤。人主內有誠信，則雖微隱之物，信皆及矣。莫不得所而獲吉，故曰“豚魚吉”也。“利涉大川，利貞”者，微隱獲吉，顯者可知。既有誠信，光被萬物，萬物得宜，以斯涉難，何往不通？故曰“利涉大川”。信而不正，兇邪之道，故利在貞也。</p><h2 id="《彖》曰-​" tabindex="-1">《彖》曰： ​ <a class="header-anchor" href="#《彖》曰-​" aria-label="Permalink to “《彖》曰： ​”">​</a></h2><h3 id="中孚-柔在內而剛得中-說而巽-​" tabindex="-1">中孚，柔在內而剛得中，說而巽， ​ <a class="header-anchor" href="#中孚-柔在內而剛得中-說而巽-​" aria-label="Permalink to “中孚，柔在內而剛得中，說而巽， ​”">​</a></h3><p>王弼：孚，有上四德，然後乃孚。</p><h3 id="疏-1" tabindex="-1">疏 <a class="header-anchor" href="#疏-1" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：此就三、四陰柔並在兩體之內，二、五剛德各處一卦之中，及上下二體說而以巽，釋此卦名為“中孚”之義也。柔內剛中，各當其所，說而以巽，乖爭不作，所以信發於內，謂之“中孚”，故曰“柔在內而剛得中，說而巽，孚”也。</p><h3 id="乃化邦也。-​" tabindex="-1">乃化邦也。 ​ <a class="header-anchor" href="#乃化邦也。-​" aria-label="Permalink to “乃化邦也。 ​”">​</a></h3><p>王弼：信立而後邦乃化也。柔在內而剛得中，各當其所也。剛得中，則直而正；柔在內，則靜而順；說而以巽，則乖爭不作。如此，則物無巧競，敦實之行著，而篤信發乎其中矣。</p><h3 id="疏-2" tabindex="-1">疏 <a class="header-anchor" href="#疏-2" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：誠信發於內，則邦國化於外，故曰“乃化邦也”。</p><h3 id="豚魚吉-信及豚魚也。-​" tabindex="-1">“豚魚吉”，信及豚魚也。 ​ <a class="header-anchor" href="#豚魚吉-信及豚魚也。-​" aria-label="Permalink to ““豚魚吉”，信及豚魚也。 ​”">​</a></h3><p>王弼：魚者，蟲之隱者也。豚者，獸之微賤者也。爭競之道不興，中信之德淳著，則雖微隱之物，信皆及之。</p><h3 id="疏-3" tabindex="-1">疏 <a class="header-anchor" href="#疏-3" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋所以得吉，由信及豚魚故也。</p><h3 id="利涉大川-乘木舟虛也。-​" tabindex="-1">“利涉大川”，乘木舟虛也。 ​ <a class="header-anchor" href="#利涉大川-乘木舟虛也。-​" aria-label="Permalink to ““利涉大川”，乘木舟虛也。 ​”">​</a></h3><p>王弼：乘木於川舟之虛，則終已無溺也。用中孚以涉難，若乘木舟虛也。</p><h3 id="疏-4" tabindex="-1">疏 <a class="header-anchor" href="#疏-4" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋此涉川所以得利，以中信而濟難，若乘虛舟以涉川也。</p><h3 id="中孚以-利貞-乃應乎天也。-​" tabindex="-1">中孚以“利貞”，乃應乎天也。 ​ <a class="header-anchor" href="#中孚以-利貞-乃應乎天也。-​" aria-label="Permalink to “中孚以“利貞”，乃應乎天也。 ​”">​</a></h3><p>王弼：盛之至也。</p><h3 id="疏-5" tabindex="-1">疏 <a class="header-anchor" href="#疏-5" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：釋中孚所以利貞者，天德剛正而氣序不差，是正而信也。今信不失正，乃得應於天，是中孚之盛故須濟以利貞也。</p><h2 id="《象》曰-澤上有風-中孚。君子以議獄緩死。-​" tabindex="-1">《象》曰：澤上有風，中孚。君子以議獄緩死。 ​ <a class="header-anchor" href="#《象》曰-澤上有風-中孚。君子以議獄緩死。-​" aria-label="Permalink to “《象》曰：澤上有風，中孚。君子以議獄緩死。 ​”">​</a></h2><p>王弼：信發於中，雖過可亮。</p><h3 id="疏-6" tabindex="-1">疏 <a class="header-anchor" href="#疏-6" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“澤上有風，中孚”者，風行澤上，無所不周，其猶信之被物，無所不至，故曰“澤上有風，中孚”。“君子以議獄緩死”者，中信之世，必非故犯過失為辜，情在可恕，故君子以議其過失之獄，緩舍當死之刑也。</p><h2 id="初九-虞吉-有它不燕。-​" tabindex="-1">初九：虞吉，有它不燕。 ​ <a class="header-anchor" href="#初九-虞吉-有它不燕。-​" aria-label="Permalink to “初九：虞吉，有它不燕。 ​”">​</a></h2><p>王弼：虞猶專也。為信之始，而應在四，得乎專吉者也，志未能變，繫心於一，故“有它不燕”也。</p><h3 id="疏-7" tabindex="-1">疏 <a class="header-anchor" href="#疏-7" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：虞猶專也。燕，安也。初為信始，應在於四，得其專一之吉，故曰“虞吉”。既繫心於一，故更有他求，不能與之共相燕安也，故曰“有它不燕”也。</p><h3 id="《象》曰-初九-虞吉-志未變也。-​" tabindex="-1">《象》曰：“初九，虞吉”，志未變也。 ​ <a class="header-anchor" href="#《象》曰-初九-虞吉-志未變也。-​" aria-label="Permalink to “《象》曰：“初九，虞吉”，志未變也。 ​”">​</a></h3><h3 id="疏-8" tabindex="-1">疏 <a class="header-anchor" href="#疏-8" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“志未變”者，所以得專一之吉，以志未改變，不更親於他也。</p><h2 id="九二-鶴鳴在陰-其子和之。我有好爵-吾與爾靡之。-​" tabindex="-1">九二：鶴鳴在陰，其子和之。我有好爵，吾與爾靡之。 ​ <a class="header-anchor" href="#九二-鶴鳴在陰-其子和之。我有好爵-吾與爾靡之。-​" aria-label="Permalink to “九二：鶴鳴在陰，其子和之。我有好爵，吾與爾靡之。 ​”">​</a></h2><p>王弼：處內而居重陰之下，而履不失中，不徇於外，任其真者也。立誠篤至，雖在闇昧，物亦應焉，故曰“鳴鶴在陰，其子和之”也。不私權利，唯德是與，誠之至也，故曰我有好爵，與物散之。</p><h3 id="疏-9" tabindex="-1">疏 <a class="header-anchor" href="#疏-9" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“鳴鶴在陰，其子和之”者，九二體剛，處於卦內，又在三四重陰之下，而履不失中，是不徇於外，自任其真者也。處於幽昧，而行不失信，則聲聞於外，為同類之所應焉。如鶴之鳴於幽遠，則為其子所和，故曰“鳴鶴在陰，其子和之”也。“我有好爵，吾與爾靡之”者，靡，散也，又無偏應，是不私權利，惟德是與。若我有好爵，吾原與爾賢者分散而共之，故曰“我有好爵，吾與爾靡之。”</p><h3 id="《象》曰-其子和之-中心願也。-​" tabindex="-1">《象》曰：“其子和之”，中心願也。 ​ <a class="header-anchor" href="#《象》曰-其子和之-中心願也。-​" aria-label="Permalink to “《象》曰：“其子和之”，中心願也。 ​”">​</a></h3><h3 id="疏-10" tabindex="-1">疏 <a class="header-anchor" href="#疏-10" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“中心願”者，誠信之人，願與同類相應，得誠信而應之，是中心願也。</p><h2 id="六三-得敵-或鼓或罷-或泣或歌。-​" tabindex="-1">六三：得敵，或鼓或罷，或泣或歌。 ​ <a class="header-anchor" href="#六三-得敵-或鼓或罷-或泣或歌。-​" aria-label="Permalink to “六三：得敵，或鼓或罷，或泣或歌。 ​”">​</a></h2><p>王弼：三居少陰之上，四居長陰之下，對而不相比，敵之謂也。以陰居陽，欲進者也。欲進而閡敵，故或鼓也。四履正而承五，非己所克，故或罷也。不勝而退，懼見侵陵，故或泣而憂悲也。四履於順。不與物校，退而不見害，故或歌也。不量其力，進退無恆，憊可知也。</p><h3 id="疏-11" tabindex="-1">疏 <a class="header-anchor" href="#疏-11" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：六三與四，俱是陰爻，相與為類。然三居少陰之桑四居長陰之下，各自有應對，而不相比，敵之謂也。故曰“得敵欲進”。礙四，恐其害己，故或鼓而攻之，而四履正承尊，非己所勝，故或罷而退敗也。不勝而退，懼見侵陵，故或泣而憂悲也。四履於順，不與物校，退不見害，故或歌而歡樂也，故曰“或鼓或罷，或泣或歌”也。</p><h3 id="《象》曰-或鼓或罷-位不當也。-​" tabindex="-1">《象》曰：“或鼓或罷”，位不當也。 ​ <a class="header-anchor" href="#《象》曰-或鼓或罷-位不當也。-​" aria-label="Permalink to “《象》曰：“或鼓或罷”，位不當也。 ​”">​</a></h3><h3 id="疏-12" tabindex="-1">疏 <a class="header-anchor" href="#疏-12" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“位不當”者，所以或鼓或罷，進退無恆者，止為不當其位，妄進故也。</p><h2 id="六四-月幾望-馬匹亡-無咎。-​" tabindex="-1">六四：月幾望，馬匹亡，無咎。 ​ <a class="header-anchor" href="#六四-月幾望-馬匹亡-無咎。-​" aria-label="Permalink to “六四：月幾望，馬匹亡，無咎。 ​”">​</a></h2><p>王弼：居中孚之時，處巽之始，應說之初，居正履順，以承於五，內毗無首，外宣德化者也。充乎陰德之盛，故曰：“月幾望”。“馬匹亡”者，棄群類也。若夫居盛德之位，而與物校其競爭，則失其所盛矣，故曰絕類而上，履正承尊，不與三爭，乃得無咎也。</p><h3 id="疏-13" tabindex="-1">疏 <a class="header-anchor" href="#疏-13" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“月幾望”者，六四居中孚之時，處巽應說，得位履順，上承於五，內毗元首，外宣德化，充乎陰德之盛，如月之近望，故曰“月幾望”也。“馬匹亡，無咎”者，三與己敵，進來攻己，己若與三校戰，則失其所盛，故棄三之類，如馬之亡匹；上承其五，不與三爭，乃得無咎，故曰“馬匹亡，無咎”也。</p><h3 id="《象》曰-馬匹亡-絕類上也。-​" tabindex="-1">《象》曰：“馬匹亡”，絕類上也。 ​ <a class="header-anchor" href="#《象》曰-馬匹亡-絕類上也。-​" aria-label="Permalink to “《象》曰：“馬匹亡”，絕類上也。 ​”">​</a></h3><p>王弼：類謂三，俱陰爻，故曰“類”也。</p><h3 id="疏-14" tabindex="-1">疏 <a class="header-anchor" href="#疏-14" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“絕類上”者，絕三之類，不與二爭，而上承於五也。</p><h2 id="九五-有孚攣如-無咎。-​" tabindex="-1">九五：有孚攣如，無咎。 ​ <a class="header-anchor" href="#九五-有孚攣如-無咎。-​" aria-label="Permalink to “九五：有孚攣如，無咎。 ​”">​</a></h2><p>王弼：“攣如”者，系其信之辭也。處中誠以相交之時，居尊位以為群物之主，信何可舍？故“有孚攣如”，乃得“無咎”也。</p><h3 id="疏-15" tabindex="-1">疏 <a class="header-anchor" href="#疏-15" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“有孚攣如，無咎”者，攣如者，相牽繫不絕之名也。五在信時，處於尊位，為群物之主，恆須以中誠交物，孚信何可暫舍，故曰“有孚攣如”。系信不絕，乃得無咎，故曰“有孚攣如，無咎”也。</p><h3 id="《象》曰-有孚攣如-位正當也。-​" tabindex="-1">《象》曰：“有孚攣如”，位正當也。 ​ <a class="header-anchor" href="#《象》曰-有孚攣如-位正當也。-​" aria-label="Permalink to “《象》曰：“有孚攣如”，位正當也。 ​”">​</a></h3><h3 id="疏-16" tabindex="-1">疏 <a class="header-anchor" href="#疏-16" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“位正當”者，以其正當尊位，故戒以系信，乃得無咎。若真以陽得正位，而無有系信，則招有咎之嫌也。</p><h2 id="上九-翰音登於天-貞兇。-​" tabindex="-1">上九：翰音登於天，貞兇。 ​ <a class="header-anchor" href="#上九-翰音登於天-貞兇。-​" aria-label="Permalink to “上九：翰音登於天，貞兇。 ​”">​</a></h2><p>王弼：翰，高飛也。飛音者，音飛而實不從之謂也。居卦之上，處信之終，信終則衰，忠篤內喪，華美外揚，故曰“翰音登於天”也。翰音登天，正亦滅矣。</p><h3 id="疏-17" tabindex="-1">疏 <a class="header-anchor" href="#疏-17" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：翰，高飛也。飛音者，音飛而實不從之謂也。上九處信之終信終則衰也。信衰則詐起，而忠篤內喪，華美外揚，若鳥於翰音登於天，虛聲遠聞也，故曰“翰音登於天”。虛聲無實，正之兇也，故曰“貞兇”。</p><h3 id="《象》曰-翰音登於天-何可長也。-​" tabindex="-1">《象》曰：“翰音登於天”，何可長也。 ​ <a class="header-anchor" href="#《象》曰-翰音登於天-何可長也。-​" aria-label="Permalink to “《象》曰：“翰音登於天”，何可長也。 ​”">​</a></h3><h3 id="疏-18" tabindex="-1">疏 <a class="header-anchor" href="#疏-18" aria-label="Permalink to “疏”">​</a></h3><p>正義曰：“何可長也”者，虛聲無實，何可久長。</p>',74)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
